<script setup>
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {ElMessage} from 'element-plus';
import {api,postJson,formatTime} from '../api';
import {preferences} from '../composables/preferences';
import {badgeColor} from '../composables/presentation';
import {registerPageRefresher} from '../composables/pageRefresh';
import {usePagination} from '../composables/pagination';
import UiContentState from '../components/UiContentState.vue';
import peopleVideo from '../assets/people-detection.mp4';
import factoryVideo from '../assets/factory-people-demo.mp4';
import corridorVideo from '../assets/corridor-review.webm';
import demoPoster from '../assets/evidence-concept.jpg';
const records=ref([]),selected=ref(null),filter=ref('all'),media=ref('image'),error=ref(''),saving=ref(false),drafts=ref({});const loading=ref(true);let unregister,loaded=false,controller,disposed=false;
const videos=[{id:'video-demo-people',title:'人员检测视频',video:peopleVideo,description:'人员检测演示片段。'},{id:'video-demo-factory',title:'工厂场景视频',video:factoryVideo,description:'工厂场景演示片段。'},{id:'video-demo-corridor',title:'巡检图片回放',video:corridorVideo,description:'将历史巡检图片整理为回放片段，并非实时录像。'}].map(v=>({...v,type:'视频演示',time:null,image:demoPoster,value:'未记录',demo:true}));
function eventTime(value){
 if(value==null||value==='')return Number.NEGATIVE_INFINITY;
 const numeric=Number(value);
 if(Number.isFinite(numeric))return numeric<1e12?numeric*1000:numeric;
 const parsed=Date.parse(value);
 return Number.isFinite(parsed)?parsed:Number.NEGATIVE_INFINITY;
}
const sorted=computed(()=>records.value.map((item,index)=>({item,index})).sort((a,b)=>eventTime(b.item.time)-eventTime(a.item.time)||a.index-b.index).map(({item})=>item));
const pending=computed(()=>sorted.value.filter(r=>r.alert&&!r.note?.handled));
const filtered=computed(()=>filter.value==='pending'?pending.value:filter.value==='video'?videos:sorted.value);
const {page,pageSize,visible}=usePagination(filtered);
const initialLoading=computed(()=>loading.value&&!loaded&&filter.value!=='video');
const status=item=>item?.demo?'演示素材':item?.note?.handled?'已处理':item?.alert?'待处理':'已记录';
const noteText=computed({get:()=>selected.value?(drafts.value[selected.value.id]??selected.value.note?.text??selected.value.description??''):'',set:v=>{if(selected.value)drafts.value[selected.value.id]=v;}});
watch(filter,()=>{page.value=1;select(filtered.value[0]);});
function select(item){selected.value=item||null;media.value=item?.video?'video':'image';}
async function saveNote(handled=false){if(!selected.value||saving.value)return;saving.value=true;const item=selected.value;try{const result=await postJson('/api/studio/event-note',{event_id:item.id,text:noteText.value,handled:handled||Boolean(item.note?.handled)});item.note=result.note;const original=records.value.find(r=>r.id===item.id);if(original)original.note=result.note;delete drafts.value[item.id];ElMessage.success(handled?'处理结果已保存':'事件说明已保存');}catch(e){ElMessage.error(e.message||'保存失败，输入内容已保留');}finally{saving.value=false;}}
function related(){if(selected.value?.related)document.dispatchEvent(new CustomEvent('studio-page-change',{detail:selected.value.related}));}
async function load(){if(controller||disposed)return;const request=new AbortController();controller=request;loading.value=true;error.value='';try{const data=await api('/api/studio/events',{signal:AbortSignal.any([request.signal,AbortSignal.timeout(12000)])});if(disposed)return;const items=data.records||[];for(const video of videos)video.note=data.video_notes?.[video.id]||{};if(loaded&&preferences.alertNotice&&items.some(item=>item.alert&&!records.value.some(old=>old.id===item.id)))ElMessage.warning('有新的告警记录');records.value=items;loaded=true;if(filter.value!=='video'){selected.value=selected.value?items.find(r=>r.id===selected.value.id)||filtered.value[0]:filtered.value[0];}error.value='';}catch{if(!disposed)error.value='请检查设备连接后重试。';}finally{loading.value=false;controller=null;}}
onMounted(()=>{load();unregister=registerPageRefresher('alerts',load);});onBeforeUnmount(()=>{disposed=true;controller?.abort();unregister?.();});
</script>
<template>
<div class="stats-row"><button class="stat-card" @click="filter='pending'"><span class="icon-box red-soft"><UiIcon name="alert"/></span><div><div class="label">待处理</div><b class="number red">{{initialLoading?'—':pending.length}}<small>条</small></b></div></button><article class="stat-card"><span class="icon-box"><UiIcon name="file"/></span><div><div class="label">记录总数</div><b class="number">{{initialLoading?'—':records.length}}<small>条</small></b></div></article><article class="stat-card"><span class="icon-box"><UiIcon name="check"/></span><div><div class="label">已处理</div><b class="number green">{{initialLoading?'—':records.filter(r=>r.note?.handled).length}}<small>条</small></b></div></article><button class="stat-card" @click="filter='video'"><span class="icon-box"><UiIcon name="play"/></span><div><div class="label">视频记录</div><b class="number">{{videos.length}}<small>段</small></b></div></button></div>
<div class="alert-grid">
 <UiCard title="告警记录" glyph="alert"><template #extra><span v-if="loading&&loaded" class="history-refresh-label" role="status">正在更新…</span></template><div class="table-tools"><div class="tabbar"><button class="tab" :class="{active:filter==='all'}" @click="filter='all'">全部记录</button><button class="tab" :class="{active:filter==='pending'}" @click="filter='pending'">待处理 {{pending.length}}</button><button class="tab" :class="{active:filter==='video'}" @click="filter='video'"><UiIcon name="play" :size="13"/>视频 {{videos.length}}</button></div></div><div v-if="error&&visible.length&&filter!=='video'" class="history-error" role="status">记录更新失败，已保留上次结果<button class="btn plain" @click="load">重试</button></div><div class="record-list" :class="{'has-state':!visible.length}" :aria-busy="loading&&filter!=='video'"><div v-for="item in visible" :key="item.id" class="alert-row" :class="{active:item.id===selected?.id}"><div class="alert-row-top"><b :class="item.demo?'':item.alert||item.result_state==='failure'?'red':'green'">{{item.title}}</b><time>{{item.time?formatTime(item.time):'演示视频'}}</time></div><div class="alert-row-badges"><span class="badge" :class="item.alert?'red':''">{{item.type}}</span><span class="badge" :class="badgeColor(status(item))">{{status(item)}}</span><span v-if="item.source_label" class="subtle">{{item.source_label}}</span></div><div class="alert-row-detail"><span>{{item.note?.text||item.description}}</span><button class="btn plain" @click="select(item)">查看 / 处理<UiIcon name="arrow" :size="15"/></button></div></div><UiContentState v-if="initialLoading" loading skeleton title="正在读取告警记录" description="正在获取事件与处理状态"/><UiContentState v-else-if="!visible.length&&error&&filter!=='video'" icon="wifi" title="告警记录暂时无法读取" :description="error" retry @retry="load"/><UiContentState v-else-if="!visible.length" :icon="filter==='pending'?'check':'file'" :title="filter==='pending'?'暂无待处理告警':'还没有告警记录'" :description="filter==='pending'?'后续需要处理的事件会显示在这里':'设备产生事件后，记录将显示在这里'"/></div><UiPagination v-model="page" v-model:page-size="pageSize" :total="filtered.length"/></UiCard>
 <UiCard title="事件详情与证据" glyph="eye" class="evidence-card"><div class="evidence-info refined-evidence"><div><small>事件类型</small><b>{{selected?.type||'—'}}</b></div><div><small>记录时间</small><b class="number">{{selected?.time?formatTime(selected.time,{seconds:true}):'—'}}</b></div><div><small>处理状态</small><span class="badge" :class="badgeColor(status(selected))">{{selected?status(selected):'—'}}</span></div><div><small>关联仪表读数</small><b :class="selected?.alert?'red':''">{{selected?.value??'未记录'}}</b></div><div class="wide event-note"><div class="note-label"><label for="event-description">事件说明</label><button class="btn primary note-save-button" :disabled="!selected||saving" @click="saveNote(false)"><UiIcon name="check" :size="14"/>{{saving?'保存中…':'保存说明'}}</button></div><textarea id="event-description" v-model="noteText" :disabled="!selected||saving" maxlength="2000" rows="3" placeholder="填写事件经过、复核情况或处理说明"></textarea><small v-if="selected?.note?.updated_at" class="note-saved-time" role="status">最近保存 {{formatTime(selected.note.updated_at,{seconds:true})}}</small></div></div><div class="evidence-header"><div class="tabbar"><button class="tab" :class="{active:media==='image'}" @click="media='image'"><UiIcon name="camera" :size="13"/>图片</button><button class="tab" :class="{active:media==='video'}" @click="media='video'"><UiIcon name="play" :size="13"/>视频</button></div><span v-if="selected?.demo" class="badge amber">演示素材</span></div><div class="evidence-image" :aria-busy="initialLoading"><video v-if="media==='video'&&selected?.video" :key="selected.id" :src="selected.video" controls preload="metadata"></video><img v-else-if="media==='image'&&selected?.image" :src="selected.image" alt="所选事件的采集证据"><UiContentState v-else-if="initialLoading" loading title="正在加载事件证据" description="记录读取完成后显示对应图片与视频"/><UiContentState v-else-if="error&&!selected&&filter!=='video'" icon="wifi" title="事件证据暂时无法读取" description="重新加载告警记录后查看证据" retry @retry="load"/><UiContentState v-else :icon="media==='video'?'play':'camera'" :title="selected?(media==='video'?'本记录未采集视频':'本记录未采集图片'):'等待选择事件'" :description="selected?'可切换图片或视频，查看其他证据':'选择左侧记录，在这里查看现场证据'"/></div><div v-if="media==='image'" class="evidence-thumbnails" aria-label="切换事件图片"><button v-for="item in filtered.filter(r=>r.image).slice(0,4)" :key="item.id" :class="{active:item.id===selected?.id}" :aria-label="'查看'+item.title" @click="select(item)"><img :src="item.image" :alt="item.title" loading="lazy"></button></div><div class="action-row centered evidence-actions"><button class="btn primary" :disabled="!selected||selected.demo||selected.note?.handled||saving" @click="saveNote(true)"><UiIcon name="check" :size="15"/>确认处理</button><button class="btn" :disabled="!selected?.related||selected.demo" :title="selected?.related?'打开本事件对应的原始记录':'本事件没有可跳转的业务记录'" @click="related"><UiIcon name="file" :size="15"/>查看关联记录</button></div></UiCard>
</div>
</template>

<style scoped>
.record-list.has-state{display:flex;flex-direction:column}.evidence-image{display:flex;align-items:stretch}.evidence-image>img,.evidence-image>video{min-width:0;align-self:stretch}.history-refresh-label{font-size:11px;color:var(--muted)}.history-error{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 18px;font-size:11px;color:var(--amber);border-bottom:1px solid var(--line)}
</style>